/**
 * The http binding: `HeedApi` over the Heed service, through a client typed from the API contract
 * (src/contract). It needs the contract's routes only, not its schemas (the service validates),
 * so it reads them from `contract.json`, generated by `npm run api:generate`. Loaded on demand.
 *
 * Wired so far: the session, the workspace's people and domains, the library list, the
 * definitions with the terms and synonyms written here and their writes (P7b), search everywhere,
 * comments with their reactions and mentions, the Inbox and the review (the golden plan's P6b),
 * and Ask on the answer engine, with the person's chats kept in their browser (P10, http-ask.ts).
 * Every other method answers `not-available` until the pull request that wires its screen
 * (P7 to P13). The conformance suite
 * (tests/app/conformance/heed-api.ts) runs the wired ones. Changes carry the session's token in
 * `X-Heed-CSRF`, as the service requires, and a retry key, kept until the service answers; the
 * session cookie is HttpOnly, so the token is read from `auth.session`.
 */
import { createORPCClient } from '@orpc/client'
import type { AnyContractRouter, ContractRouterClient } from '@orpc/contract'
import { OpenAPILink } from '@orpc/openapi-client/fetch'
import type { Asked, LookupEvent } from '@contract/answer'
import type { Contract } from '@contract/index'
import type { Feed } from '@contract/inbox'
import { refusals } from '@contract/refusals'
import type { ReviewSheet } from '@contract/review-path'
import { ABOUT_BUSINESS_STARTER } from '@domain/about-business'
import { canonicalJson } from '@domain/canonical'
import type { CardAction } from '@domain/inbox'
import { plainOf } from '@/components/templates/comment-box/utils'
import { reportedOn, reportOutcomeWords } from '@/model/ask'
import type { Domains } from '@/model/people'
import routes from './contract.json' with { type: 'json' }
import { heedApiMethods, type HeedApi, type HeedApiMethod, type Session } from './client'
import { ApiError, toApiError } from './errors'
import {
  answerOf,
  askedWeekOf,
  browserShelf,
  createChatShelf,
  examplesOf,
  failedAnswer,
  lookupFields,
  namesOf,
  nothingLiveAnswer,
  type ReadScope,
  type Shelf,
} from './http-ask'
import { inboxOf, refOf, reviewOf, workspaceOf, type SheetRef } from './http-inbox'
import {
  bodyToService,
  commentsOf,
  definitionsOf,
  factsOf,
  hitsOf,
  refusalOf,
  termDefinitionsOf,
  type Names,
  type People,
} from './http-map'

export type HttpApiOptions = {
  /** Absolute URL of the API, with its version prefix: `https://host/api/v1`. */
  baseUrl: string
  fetch?: typeof globalThis.fetch
  /** Where the person's Ask chats are kept: the browser's local storage by default. */
  shelf?: Shelf
}

type CallContext = { headers?: Record<string, string> }

/** The methods this binding answers so far. */
export const wiredMethods = [
  'getSession',
  'listSignInPeople',
  'signIn',
  'signOut',
  'getWorkspace',
  'getVocabulary',
  'getLibrary',
  'getDefinitions',
  'saveTerm',
  'addSynonym',
  'removeTerm',
  'deleteTerms',
  'moveTerms',
  'searchAll',
  'getComments',
  'postComment',
  'reactToComment',
  'reactToSubject',
  'editComment',
  'removeComment',
  'markThreadSeen',
  'markMentionSeen',
  'getInbox',
  'inboxPage',
  'getReviews',
  'markOpened',
  'markReviewed',
  'decideCard',
  'completeCard',
  'publishReview',
  'publishReviews',
  'archiveReview',
  'returnReview',
  'undo',
  'getConnectReview',
  'setAbout',
  'completeSetupStep',
  'readQuestion',
  'ask',
  'askedThisWeek',
  'getAskExamples',
  'listChats',
  'saveChat',
  'renameChat',
  'deleteChat',
  'reportAnswer',
  'getMyReports',
] as const satisfies readonly HeedApiMethod[]

/**
 * Reads the shell and the Inbox draw from but whose own screens a later pull request wires: they
 * answer what the service holds for them today, which is nothing, so those screens draw. Their
 * writes stay not available, and the conformance suite does not count them as wired.
 */
const pending: Partial<HeedApi> = {
  // Saved questions and their check come with Observability (P12).
  getSavedQuestions: () => Promise.resolve([]),
  getSavedCheck: () => Promise.resolve({ run: 'idle', checked: 0 }),
  getSavedViews: () => Promise.resolve([]),
  // Settings and the agents connected (P11a).
  getSettings: () => Promise.resolve({ links: false, figures: {}, contacts: {}, connected: [] }),
  listAgentConnections: () => Promise.resolve([]),
}

const emptyHits = () => ({ items: [], definitions: [], domains: [], people: [] })

const notAvailable = (method: string) => () =>
  Promise.reject(new ApiError('not-available', `The service doesn't offer this yet (${method}).`))

/** The service refused a change for its token: a newer session has a new one. */
const csrfRefused = (error: unknown) =>
  toApiError(error).kind === 'forbidden' && toApiError(error).message === refusals.csrf

/** A card's decision in the service's words, by the outcome the Inbox names it with. */
const cardActions: Record<string, CardAction> = {
  Checked: 'still_true',
  'Not a problem': 'not_a_problem',
  Closed: 'not_written',
  'Not something we write down': 'not_written',
  Archived: 'archive',
}

const isUuid = (id: string) =>
  /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(id)

const randomKey = () => globalThis.crypto.randomUUID()

/** Two names for the same word: case aside. */
const same = (a: string, b: string) => a.toLowerCase() === b.toLowerCase()

export function createHttpApi({ baseUrl, fetch, shelf }: HttpApiOptions): HeedApi {
  const link = new OpenAPILink<CallContext>(routes as unknown as AnyContractRouter, {
    url: baseUrl,
    headers: ({ context }) => context.headers ?? {},
    ...(fetch ? { fetch: (request, init) => fetch(request, init) } : {}),
  })
  const client: ContractRouterClient<Contract, CallContext> = createORPCClient(link)

  /** The token of the latest session read; every change sends it. */
  let csrfToken: string | undefined
  /** Who is signed in, as the latest session read says. */
  let me: { id: string; name: string; admin: boolean } | undefined
  /** Who the sign-in offers, by name, so a name signs in as that person's address. */
  let offered: { name: string; email: string }[] = []
  /** What a review's decisions need, by the card it is reviewed from. */
  const refs = new Map<string, SheetRef>()
  /** The retry key of each change still waiting for an answer. */
  const pendingKeys = new Map<string, string>()

  async function read<T>(call: () => Promise<T>): Promise<T> {
    try {
      return await call()
    } catch (error) {
      throw toApiError(error)
    }
  }

  async function session() {
    const current = await read(() => client.auth.session())
    csrfToken = current.csrfToken
    me = {
      id: current.person.id,
      name: current.person.name,
      admin: current.person.permissions.roles.includes('administrator'),
    }
    return { ...current, me }
  }
  const signedIn = async () => me ?? (await session()).me

  /**
   * A change. Its retry key stays the same for the same operation and input until the service
   * answers, so a change sent again after no answer is applied once.
   */
  async function write<T>(
    operation: string,
    input: unknown,
    call: (options: { context: CallContext }) => Promise<T>,
  ): Promise<T> {
    const id = `${operation} ${canonicalJson(JSON.parse(JSON.stringify(input ?? null)))}`
    const key = pendingKeys.get(id) ?? randomKey()
    pendingKeys.set(id, key)
    const send = (token: string) =>
      call({ context: { headers: { 'x-heed-csrf': token, 'idempotency-key': key } } })
    try {
      let result: T
      try {
        result = await send(csrfToken ?? (await session()).csrfToken)
      } catch (error) {
        if (!csrfRefused(error)) throw error
        result = await send((await session()).csrfToken)
      }
      pendingKeys.delete(id)
      return result
    } catch (error) {
      const failure = toApiError(error)
      if (!failure.retryable) pendingKeys.delete(id)
      throw failure
    }
  }

  /**
   * A read the service takes as a POST, so a question's words travel in the body and never in an
   * address: like a change, it carries the session's token, but needs no retry key.
   */
  async function readPosted<T>(call: (options: { context: CallContext }) => Promise<T>) {
    const send = (token: string) =>
      read(() => call({ context: { headers: { 'x-heed-csrf': token } } }))
    try {
      return await send(csrfToken ?? (await session()).csrfToken)
    } catch (error) {
      if (!csrfRefused(error)) throw error
      return send((await session()).csrfToken)
    }
  }

  const asSession = (name: string): Session => ({ user: name, install: 'normal', fresh: false })

  /** Everyone the comments may name, both ways: by id, and by name for a mention. */
  async function readPeople(): Promise<People> {
    const people = await read(() => client.people.list())
    const name = new Map(people.map((p) => [p.id, p.name]))
    const id = new Map(people.map((p) => [p.name, p.id]))
    return { name: (personId) => name.get(personId) ?? 'Someone', idOf: (n) => id.get(n) }
  }

  /** The people and the domains, read beside an answer that names them by id. */
  async function readPeopleAndAreas() {
    const [people, areas, who] = await Promise.all([
      read(() => client.people.list()),
      read(() => client.areas.list()),
      signedIn(),
    ])
    return { listed: { people, areas }, workspace: workspaceOf({ people, areas, me: who }) }
  }

  /** Who the answers name by id: the people and the domains, read beside them. */
  async function readNames(): Promise<Names> {
    const { people, areas } = (await readPeopleAndAreas()).listed
    const name = new Map(people.map((p) => [p.id, p.name]))
    const owners = new Map(areas.map((a) => [a.id, a.ownerIds]))
    const person = (id: string) => name.get(id) ?? 'Someone'
    return { person, domainOwners: (areaId) => (owners.get(areaId) ?? []).map(person) }
  }

  /** The metrics and dimensions the catalogue lists, the terms written here, and who wrote them. */
  async function readGlossary() {
    const [catalogue, { terms }, people] = await Promise.all([
      read(() => client.catalogue.list()),
      read(() => client.terms.list()),
      readPeople(),
    ])
    return {
      terms,
      definitions: [...definitionsOf(catalogue.terms), ...termDefinitionsOf(terms, people.name)],
      /** What a name means on the service: a metric's or a dimension's key, or a term's id. */
      refOf(name: string) {
        const key = catalogue.terms.find((t) => same(t.name, name))?.key
        const term = terms.find((t) => same(t.name, name))
        const ref = key ?? (term ? `term:${term.id}` : undefined)
        if (!ref) throw new ApiError('not-found', `“${name}” isn't in Definitions any more.`)
        return ref
      },
      /** The terms written here with these names; a synced definition is never one. */
      idsOf: (names: readonly string[]) =>
        terms.filter((t) => names.some((n) => same(n, t.name))).map((t) => t.id),
    }
  }

  /** A change to many terms: its Undo, or why none of them changed. */
  const undoOf = (done: { undo: string | null; skipped: { message: string }[] }) => {
    if (!done.undo)
      throw new ApiError('conflict', done.skipped[0]?.message ?? 'None of them could be changed.')
    return { undo: done.undo }
  }

  /** The person's Inbox as the service has it: needs and all, done and waiting. */
  const readFeed = () => read(() => client.inbox.feed({ tab: 'all' }))

  async function inbox() {
    const [feed, { workspace, listed }, who] = await Promise.all([
      readFeed(),
      readPeopleAndAreas(),
      signedIn(),
    ])
    const byId: Domains = Object.fromEntries(workspace.domains.map((d) => [d.id, d]))
    readGaps(feed)
    const name = new Map(listed.people.map((p) => [p.id, p.name]))
    return {
      ...inboxOf(feed, who.name, byId, new Date(), (id) => name.get(id) ?? 'Someone'),
      sent: [],
    }
  }

  /** A Not found card's draft, by the draft's id, with its card: the app names the card by the draft. */
  const gaps = new Map<string, { card: string; times: number | null }>()
  const readGaps = (feed: Feed) => {
    for (const c of feed.cards)
      if (c.group === 'gap' && c.draft) gaps.set(c.draft, { card: c.id, times: c.times })
  }

  /**
   * The suggestions the person reviews, open and decided, each under its card's id: a Not found
   * card's draft too. Newest sent first, the order the review steps through.
   */
  async function reviews() {
    const feed: Feed = await readFeed()
    readGaps(feed)
    const drafts = new Set(
      feed.cards.flatMap((c) => (c.group === 'gap' && c.draft ? [c.draft] : [])),
    )
    const wanted = [
      ...[...drafts].map((proposal) => ({ card: proposal, proposal })),
      ...feed.cards.flatMap((c) =>
        c.group === 'suggestion' && !drafts.has(c.proposalId)
          ? [{ card: c.proposalId, proposal: c.proposalId }]
          : [],
      ),
    ]
    const sheets = (
      await Promise.all(
        wanted.map(async (w) => {
          try {
            return { ...w, sheet: await read(() => client.review.sheet({ id: w.proposal })) }
          } catch (error) {
            // One that went while the list was read is left out; anything else is a failure.
            if (toApiError(error).kind === 'not-found') return null
            throw error
          }
        }),
      )
    ).filter((x): x is { card: string; proposal: string; sheet: ReviewSheet } => x !== null)
    const sent = (s: ReviewSheet) => s.proposal.submittedAt ?? s.proposal.createdAt
    sheets.sort((a, b) =>
      sent(a.sheet) < sent(b.sheet) ? 1 : sent(a.sheet) > sent(b.sheet) ? -1 : 0,
    )
    for (const s of sheets) refs.set(s.card, refOf(s.sheet))
    return sheets.map((s) => reviewOf(s.sheet, s.card, gaps.get(s.card)))
  }

  /** What deciding on a review needs, read again when this visit has not read it yet. */
  async function refFor(card: string): Promise<SheetRef> {
    if (!refs.has(card)) await reviews()
    const ref = refs.get(card)
    if (!ref) throw new ApiError('not-found', 'This suggestion no longer waits for a decision.')
    return ref
  }

  /** A decision on a card, by its outcome in the Inbox's words. */
  const decideCard = async ({ card: id, outcome }: { card: string; outcome: string }) => {
    // A Not found card with a draft is named by its draft: its decision is the gap card's.
    const card = gaps.get(id)?.card ?? id
    const action = cardActions[outcome]
    if (!action) throw new ApiError('invalid', `A card can't be decided as “${outcome}”.`)
    const decided = await write('cards.decide', { card, action }, (o) =>
      client.cards.decide({ card, action }, o),
    )
    return { undo: decided.undo }
  }

  /** Publishes a suggestion, or archives what a retirement names: one accept by an owner. */
  const publish = async (id: string, relation?: string | null) => {
    const ref = await refFor(id)
    const relations =
      relation && ref.clashes.length
        ? ref.clashes.map((itemId) => ({
            itemId,
            relation: relation === 'disagree' ? ('disagrees' as const) : (relation as 'replaces'),
          }))
        : undefined
    const input = {
      id: ref.proposalId,
      revision: ref.revision,
      ...(relations ? { relations } : {}),
    }
    const done = await write('review.publish', input, (o) => client.review.publish(input, o))
    // Deciding gives it a new revision: the next decision on it reads it again.
    refs.delete(id)
    return { undo: done.undo }
  }

  /** What the business is about, and its version, for an admin; null for anyone else. */
  async function readAbout(): Promise<{ text: string; version: number } | null> {
    if (!(await signedIn()).admin) return null
    const setting = (await read(() => client.settings.list())).find(
      (x) => x.key === 'business.about',
    )
    return {
      text: typeof setting?.value === 'string' ? setting.value : '',
      version: setting?.version ?? 0,
    }
  }

  /* ---------- Ask ---------- */

  const chats = createChatShelf(shelf ?? browserShelf())
  /** What each question's first answer said, for its chat's line in the history search. */
  const said = new Map<string, string>()
  /** The scope each offered question asks with, by its words, so a click gets its row's state. */
  const offeredScopes = new Map<string, ReadScope>()

  const readVocabulary = () => read(() => client.vocabulary.get())

  /** Asked this week, or nothing while nothing is shared with agents yet. */
  async function readAsked(): Promise<Asked | null> {
    try {
      const asked = await read(() => client.ask.asked())
      for (const e of examplesOf(asked)) offeredScopes.set(e.question.toLowerCase(), e.scope)
      return asked
    } catch (error) {
      if (toApiError(error).status === 412) return null
      throw error
    }
  }

  /** The engine's answer to a question: its steps run on the service, the answer is the last event. */
  async function lookUp(input: { question: string } & Partial<ReturnType<typeof lookupFields>>) {
    const events = await readPosted((o) => client.ask.lookup(input, o))
    let answer: Extract<LookupEvent, { type: 'answer' }>['answer'] | undefined
    for await (const event of events) if (event.type === 'answer') answer = event.answer
    if (!answer) throw new ApiError('unanswered', 'The answer stopped before it was finished.')
    return answer
  }

  /** The look-up's fields from the @ chips: the metrics and the markets they name. */
  function chipFields(
    scope: { id: string }[] | undefined,
    names: ReturnType<typeof namesOf>,
  ): Partial<ReturnType<typeof lookupFields>> {
    const picked = (kind: string) =>
      (scope ?? []).flatMap((m) =>
        m.id.startsWith(`${kind}:`) ? [m.id.slice(kind.length + 1)] : [],
      )
    const metrics = [...picked('metric'), ...picked('term')].flatMap(
      (n) => names.metricKey(n) ?? [],
    )
    const markets = picked('market').flatMap((n) => names.marketKey(n) ?? [])
    return {
      ...(metrics.length ? { metrics } : {}),
      ...(markets.length
        ? { dimension_filters: [{ dimension: 'dim:market', values: markets }] }
        : {}),
    }
  }

  const ask: HeedApi['ask'] = async ({ question = '', parts, scope, example }) => {
    let words = question
    let offered = offeredScopes.get(question.toLowerCase())
    if (example) {
      const found = examplesOf(await readAsked()).find((e) => e.id === example)
      if (!found) throw new ApiError('not-found', 'This question is not offered any more.')
      words = found.question
      offered = found.scope
    }
    const names = namesOf(await readVocabulary())
    const fields = scope?.length ? chipFields(scope, names) : offered ? lookupFields(offered) : {}
    const extra = {
      ...(parts?.some((p) => typeof p !== 'string') ? { parts } : {}),
      ...(scope?.length ? { scope } : {}),
    }
    try {
      const answer = answerOf(await lookUp({ question: words, ...fields }), words, names, extra)
      said.set(words.toLowerCase(), answer.text.replace(/\[\d+\]/g, ''))
      return answer
    } catch (error) {
      const failure = toApiError(error)
      // Nothing is shared with agents yet: no context, so nothing applies.
      if (failure.status === 412) return { ...nothingLiveAnswer(words), ...extra }
      // The check could not run: Not checked, which is not the same as nothing written down.
      if (failure.kind === 'failed' || failure.kind === 'unanswered')
        return { ...failedAnswer(words), ...extra }
      throw failure
    }
  }

  const wired: Pick<HeedApi, (typeof wiredMethods)[number]> = {
    // A workspace whose setup checklist is unfinished is a new install: the Inbox shows the
    // checklist until it is done (docs/product.md, FR-816).
    getSession: async () => {
      try {
        const { me: who } = await session()
        const setup = await read(() => client.setup.state())
        return { ...asSession(who.name), install: setup.done ? 'normal' : 'new' }
      } catch (error) {
        if (toApiError(error).kind === 'signed-out') {
          me = undefined
          return { user: null, install: 'normal', fresh: false }
        }
        throw error
      }
    },
    listSignInPeople: async () => {
      offered = await read(() => client.auth.people())
      return offered.map((p) => p.name)
    },
    // The local sign-in carries its own fixed header instead of a session's token, which it does
    // not have yet; the answer is the new session and its token.
    signIn: async ({ name }) => {
      if (!offered.length) offered = await read(() => client.auth.people())
      const email = offered.find((p) => p.name === name)?.email
      if (!email) throw new ApiError('not-found', `${name} can't sign in here.`)
      const signed = await read(() =>
        client.auth.signIn({ email }, { context: { headers: { 'x-heed-csrf': 'dev-sign-in' } } }),
      )
      csrfToken = signed.csrfToken
      me = {
        id: signed.person.id,
        name: signed.person.name,
        admin: signed.person.permissions.roles.includes('administrator'),
      }
      refs.clear()
      return asSession(signed.person.name)
    },
    // What the business is about is an admin's setting; the setup checklist's steps are read from
    // what exists. Start from the guide fills in the worked example, an outdoor-gear retailer.
    getWorkspace: async () => {
      const [{ workspace }, setup, about] = await Promise.all([
        readPeopleAndAreas(),
        read(() => client.setup.state()),
        readAbout(),
      ])
      return {
        name: '',
        domains: workspace.domains,
        people: workspace.people,
        about: about?.text ?? '',
        aboutTemplate: ABOUT_BUSINESS_STARTER,
        setup: { done: Object.fromEntries(setup.steps.map((s) => [s.id, s.done])) },
      }
    },
    setAbout: async ({ text }) => {
      const current = await readAbout()
      if (!current)
        throw new ApiError('forbidden', 'Only an admin says what the business is about.')
      if (current.text === text) return
      const input = {
        key: 'business.about',
        version: current.version,
        value: text,
        reason: 'About our business, written in Settings.',
      }
      await write('settings.set', input, (o) => client.settings.set(input, o))
    },
    // The service reads each step from what exists (setup.state): nothing to mark by hand.
    completeSetupStep: () => Promise.resolve(),
    getVocabulary: async () => {
      const vocabulary = await read(() => client.vocabulary.get())
      const markets = vocabulary.dimensions.find((d) => d.id === 'market')?.values ?? []
      return {
        metrics: vocabulary.metrics.map((m) => ({
          name: m.name,
          group: m.group,
          facts: 0,
          definition: '',
        })),
        dimensions: vocabulary.dimensions.map((d) => ({
          name: d.name,
          values: d.values.map((v) => v.name).join(', '),
          definition: '',
        })),
        markets: markets.map((v) => v.name),
      }
    },
    getLibrary: async () => {
      const [index, names] = await Promise.all([read(() => client.library.index()), readNames()])
      // What this visit published and opened, and the bulk log, are the browser's own (P7).
      return { items: factsOf(index.items, names), published: {}, viewed: {}, log: [] }
    },
    getDefinitions: async () => (await readGlossary()).definitions,
    saveTerm: async ({ previous, term }) => {
      if (term.synced) return
      const glossary = await readGlossary()
      const fields = {
        name: term.name,
        ...(term.sameAs ? { sameAs: glossary.refOf(term.sameAs) } : { meaning: term.definition }),
        areaId: term.domain ?? null,
      }
      if (!previous) {
        await write('terms.create', fields, (o) => client.terms.create(fields, o))
        return
      }
      const was = glossary.terms.find((t) => same(t.name, previous))
      if (!was) throw new ApiError('not-found', `There is no term called “${previous}”.`)
      const input = { id: was.id, revision: was.revision, ...fields }
      await write('terms.update', input, (o) => client.terms.update(input, o))
    },
    addSynonym: async ({ target, word }) => {
      const name = word.trim().replace(/\s+/g, ' ')
      if (!name) return { ok: false, why: 'empty', reason: 'Type a word.' }
      const input = { name, sameAs: (await readGlossary()).refOf(target) }
      // A word that already means something is the synonym box's answer, not a failure.
      const refused = await write('terms.create', input, async (o) => {
        try {
          await client.terms.create(input, o)
          return null
        } catch (error) {
          const refusal = refusalOf(error)
          if (refusal) return refusal
          throw error
        }
      })
      return refused ?? { ok: true, created: true }
    },
    removeTerm: async ({ name }) => {
      const ids = (await readGlossary()).idsOf([name])
      if (!ids.length) throw new ApiError('not-found', `There is no synonym called “${name}”.`)
      const input = { ids }
      return undoOf(await write('terms.delete', input, (o) => client.terms.delete(input, o)))
    },
    // What was deleted, and by whom, is the service's to keep: the screen's log entry is its own.
    deleteTerms: async ({ names }) => {
      const input = { ids: (await readGlossary()).idsOf(names) }
      if (!input.ids.length)
        throw new ApiError('not-found', 'None of these terms is here any more.')
      return undoOf(await write('terms.delete', input, (o) => client.terms.delete(input, o)))
    },
    moveTerms: async ({ names, domain }) => {
      const input = { ids: (await readGlossary()).idsOf(names), areaId: domain }
      if (!input.ids.length)
        throw new ApiError('not-found', 'None of these terms is here any more.')
      return undoOf(await write('terms.move', input, (o) => client.terms.move(input, o)))
    },
    searchAll: async ({ q }) =>
      q.trim() ? hitsOf(await read(() => client.search.all({ q }))) : emptyHits(),
    getComments: async () => {
      const [{ threads }, people, who] = await Promise.all([
        read(() => client.comments.list({})),
        readPeople(),
        signedIn(),
      ])
      return commentsOf(threads, people, who.name, new Date())
    },
    postComment: async ({ subject, content, parentId, returned }) => {
      // A returned note is written by the return itself (returnReview), never on its own.
      if (returned)
        throw new ApiError('invalid', 'A note is returned with its suggestion, from the review.')
      const input = {
        subject,
        body: bodyToService(content, await readPeople()),
        ...(parentId ? { parentId } : {}),
      }
      const posted = await write('comments.create', input, (o) => client.comments.create(input, o))
      return { id: posted.id }
    },
    reactToComment: async ({ subject, id, emoji }) => {
      const input = { subject, commentId: id, emoji }
      await write('reactions.toggle', input, (o) => client.reactions.toggle(input, o))
    },
    reactToSubject: async ({ subject, emoji }) => {
      const input = { subject, emoji }
      await write('reactions.toggle', input, (o) => client.reactions.toggle(input, o))
    },
    editComment: async ({ id, content }) => {
      const input = { id, body: bodyToService(content, await readPeople()) }
      await write('comments.edit', input, (o) => client.comments.edit(input, o))
    },
    removeComment: async ({ id }) => {
      await write('comments.remove', { id }, (o) => client.comments.remove({ id }, o))
    },
    markThreadSeen: async ({ subject }) => {
      await write('threads.markRead', { subject }, (o) => client.threads.markRead({ subject }, o))
    },
    markMentionSeen: async ({ subject }) => {
      await write('comments.markMentionsRead', { subject }, (o) =>
        client.comments.markMentionsRead({ subject }, o),
      )
    },
    signOut: async () => {
      const token = csrfToken ?? (await session()).csrfToken
      await read(() =>
        client.auth.signOut(undefined, { context: { headers: { 'x-heed-csrf': token } } }),
      )
      csrfToken = undefined
      me = undefined
      refs.clear()
    },

    // The Inbox and the review
    getInbox: inbox,
    inboxPage: inbox,
    getReviews: reviews,
    markOpened: async ({ ids }) => {
      // A suggestion's card is named by its bare proposal id; the service names it `proposal:<id>`.
      // A Not found card named by its draft: opening it opens both.
      const cards = ids.flatMap((id) =>
        isUuid(id)
          ? [`proposal:${id}`, ...(gaps.has(id) ? [gaps.get(id)!.card] : [])]
          : /^(proposal|gap|feedback|report|check|mention):/.test(id)
            ? [id]
            : [],
      )
      if (!cards.length) return
      await write('cards.markRead', { cards }, (o) => client.cards.markRead({ cards }, o))
    },
    markReviewed: async ({ id }) => {
      const ref = await refFor(id)
      if (!ref.itemVersionId) return
      const input = { id: ref.proposalId, itemVersionId: ref.itemVersionId }
      await write('review.markRead', input, (o) => client.review.markRead(input, o))
    },
    decideCard,
    completeCard: decideCard,
    publishReview: ({ id, relation }) => publish(id, relation),
    archiveReview: ({ id }) => publish(id),
    publishReviews: async ({ ids }) => {
      const proposals = await Promise.all(ids.map(async (id) => (await refFor(id)).proposalId))
      const done = await write('review.publishRead', { ids: proposals }, (o) =>
        client.review.publishRead({ ids: proposals }, o),
      )
      for (const id of ids) refs.delete(id)
      if (!done.undo)
        throw new ApiError(
          'conflict',
          done.skipped[0]?.message ?? 'None of them could be published.',
        )
      return { undo: done.undo }
    },
    returnReview: async ({ id, note }) => {
      const ref = await refFor(id)
      const input = {
        id: ref.proposalId,
        revision: ref.revision,
        note: plainOf(note).trim(),
        body: bodyToService(note, await readPeople()),
      }
      const done = await write('review.return', input, (o) => client.review.return(input, o))
      refs.delete(id)
      return { undo: done.undo }
    },
    undo: async ({ token }) => {
      // A deleted chat is put back in the browser, where it is kept.
      if (chats.undo(token)) return
      await write('decisions.undo', { token }, (o) => client.decisions.undo({ token }, o))
      // What it put back waits again under a new revision.
      refs.clear()
    },
    // The live line's state a review address shows is the mock's own: never on the service.
    getConnectReview: () => Promise.resolve(null),

    // Ask: the engine on the live edition, and the person's chats in their browser.
    readQuestion: async ({ question }) => {
      const reading = await readPosted((o) => client.tryIt.read({ question }, o))
      return {
        metric:
          reading.about.find((t) => t.kind === 'metric' || t.kind === 'metric_group')?.name ?? '',
        markets: reading.about
          .filter((t) => t.kind === 'dimension_value' && t.dimension === 'Market')
          .map((t) => t.name),
      }
    },
    ask,
    askedThisWeek: async () => {
      const [asked, vocabulary] = await Promise.all([readAsked(), readVocabulary()])
      return askedWeekOf(asked, namesOf(vocabulary))
    },
    getAskExamples: async () =>
      examplesOf(await readAsked()).map(({ scope: _scope, ...example }) => example),
    listChats: async () => chats.list((await signedIn()).id),
    saveChat: async ({ id, question }) =>
      chats.add((await signedIn()).id, id, question, said.get(question.toLowerCase()) ?? ''),
    renameChat: async ({ id, title }) => chats.rename((await signedIn()).id, id, title),
    deleteChat: async ({ id }) => chats.remove((await signedIn()).id, id),
    // A named report: the question, the part and the words the person sent, with their name.
    reportAnswer: async ({ question, part, sources, what, correction, link }) => {
      const itemId = part === 'answer' ? sources[0] : part
      if (!itemId) throw new ApiError('invalid', 'This answer has no context item to report.')
      const input = {
        question,
        itemId,
        part: part === 'answer' ? ('answer' as const) : ('item' as const),
        what,
        ...(correction?.trim() ? { correction } : {}),
        ...(link?.trim() ? { link: link.trim() } : {}),
      }
      const sent = await write('reports.create', input, (o) => client.reports.create(input, o))
      return { id: sent.id }
    },
    getMyReports: async () => {
      const now = new Date()
      return (await read(() => client.reports.mine())).reports.map((r) => ({
        id: r.id,
        question: r.question,
        on: reportedOn(new Date(r.at), now),
        ...(r.outcome
          ? { outcome: reportOutcomeWords(r.outcome.kind, new Date(r.outcome.at)) }
          : {}),
      }))
    },
  }

  return Object.fromEntries(
    heedApiMethods.map((method) => [
      method,
      (wired as Partial<Record<HeedApiMethod, unknown>>)[method] ??
        (pending as Partial<Record<HeedApiMethod, unknown>>)[method] ??
        notAvailable(method),
    ]),
  ) as unknown as HeedApi
}
